def next_business_day(year, month, day):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def dim(y, m):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if m == 2 and is_leap(y):
            return 29
        return lengths[m-1]
    def weekday(y, m, d):
        t = [0,3,2,5,0,3,5,1,4,6,2,4]
        yy = y - 1 if m < 3 else y
        return (yy + yy//4 - yy//100 + yy//400 + t[m-1] + d) % 7
    y, m, d = year, month, day
    while True:
        if d < dim(y, m):
            d += 1
        elif m < 12:
            m += 1
            d = 1
        else:
            y += 1
            m = 1
            d = 1
        if weekday(y, m, d) not in (0, 6):
            return (y, m, d)

def count_days_in_leap_years(year1, year2):
    def leaps_up_to(y):
        return y//4 - y//100 + y//400
    leaps = leaps_up_to(year2) - leaps_up_to(year1-1)
    total_years = year2 - year1 + 1
    return total_years*365 + leaps

def year_progress_percentage(year, month, day):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    is_leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    if is_leap:
        lengths[1] = 29
    doy = sum(lengths[:month-1]) + day
    total = 366 if is_leap else 365
    return round(doy/total*100, 2)

def is_after_noon(time_str):
    h, m = time_str.split(':')
    return int(h)*60 + int(m) >= 720

def time_period_label(hour):
    if 0 <= hour <= 4:
        return 'Night'
    if 5 <= hour <= 11:
        return 'Morning'
    if 12 <= hour <= 16:
        return 'Afternoon'
    return 'Evening'

def total_minutes_across_days(day_count, time_str):
    h, m = time_str.split(':')
    return day_count*1440 + int(h)*60 + int(m)
